-- State transitions declared for GamificationChallenge (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION engagement.gamification_challenges_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('done', 'draft'), ('draft', 'inprogress'), ('inprogress', 'done'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: gamification_challenges.state % -> %', OLD."state", NEW."state";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS gamification_challenges_state_transition_check ON engagement.gamification_challenges;
CREATE TRIGGER gamification_challenges_state_transition_check
    BEFORE UPDATE OF "state" ON engagement.gamification_challenges
    FOR EACH ROW EXECUTE FUNCTION engagement.gamification_challenges_state_transition_check();
